"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { site } from "@/config/site";
import type { Product } from "@/data/catalogue";

/*
 * 3D view of the panel, built on Google's <model-viewer> web component.
 * The models in /public/models are generated by scripts/3d/generate-panels.py from the
 * catalogue measurements and colours, one per format and finish: the .glb for this view and
 * for "Im Raum ansehen" on Android (Scene Viewer), the .usdz for iPhone and iPad (AR Quick Look).
 * The colour is baked into each file because both AR apps open the file on their own, without this page.
 */

type ModelViewer = HTMLElement & {
  src: string;
  canActivateAR?: boolean;
  activateAR?: () => Promise<void>;
  cameraOrbit: string;
  cameraTarget: string;
  fieldOfView: string;
  jumpCameraToGoal?: () => void;
};

const ORBIT = "25deg 80deg auto";
const SIZE_ORBIT = "25deg 80deg 130%";

const modelFile = (product: Product, ext: "glb" | "usdz") => `/models/panel-${product.format.id}-${product.finish.id}.${ext}`;

const cm = (mm: number) => (mm / 10).toLocaleString(site.locale, { maximumFractionDigits: 1 });

export function Panel3D({ product }: { product: Product }) {
  const host = useRef<HTMLDivElement>(null);
  const stage = useRef<HTMLDivElement>(null);
  const lines = useRef<SVGSVGElement>(null);
  const viewer = useRef<ModelViewer | null>(null);
  const turned = useRef(false);
  const sizeOnRef = useRef(false);

  const [status, setStatus] = useState<"loading" | "ready" | "error">("loading");
  const [progress, setProgress] = useState(0);
  const [hintGone, setHintGone] = useState(false);
  const [sizeOn, setSizeOn] = useState(false);
  const [full, setFull] = useState(false);
  const [qr, setQr] = useState<null | { svg: string | null; text: string }>(null);

  const { widthMm, heightMm, depthMm } = product.format;
  const sizeText = `${cm(widthMm)} × ${cm(heightMm)} cm`;

  const drawLines = useCallback(() => {
    const svg = lines.current;
    const mv = viewer.current;
    const box = stage.current?.getBoundingClientRect();
    if (!svg || !mv || !box) return;
    if (!sizeOnRef.current) {
      svg.innerHTML = "";
      return;
    }
    let out = "";
    for (const [a, b] of [
      ["w0", "w1"],
      ["h0", "h1"],
    ]) {
      const ea = mv.querySelector(`[slot="hotspot-${a}"]`);
      const eb = mv.querySelector(`[slot="hotspot-${b}"]`);
      if (!ea || !eb) continue;
      const ra = ea.getBoundingClientRect();
      const rb = eb.getBoundingClientRect();
      const A = [ra.left + ra.width / 2 - box.left, ra.top + ra.height / 2 - box.top];
      const B = [rb.left + rb.width / 2 - box.left, rb.top + rb.height / 2 - box.top];
      const dx = B[0] - A[0];
      const dy = B[1] - A[1];
      const len = Math.hypot(dx, dy) || 1;
      const nx = (-dy / len) * 7;
      const ny = (dx / len) * 7;
      out += `<line x1="${A[0]}" y1="${A[1]}" x2="${B[0]}" y2="${B[1]}"/>`;
      for (const P of [A, B]) out += `<line x1="${P[0] - nx}" y1="${P[1] - ny}" x2="${P[0] + nx}" y2="${P[1] + ny}"/>`;
    }
    svg.innerHTML = out;
  }, []);

  const resetView = useCallback(() => {
    const mv = viewer.current;
    if (!mv) return;
    mv.cameraOrbit = sizeOnRef.current ? SIZE_ORBIT : ORBIT;
    mv.cameraTarget = "auto auto auto";
    mv.fieldOfView = "30deg";
  }, []);

  /* hotspots at the ends of the two measuring lines, plus the labels */
  const buildDims = useCallback(() => {
    const mv = viewer.current;
    if (!mv) return;
    mv.querySelectorAll('[slot^="hotspot-"]').forEach((el) => el.remove());
    if (sizeOnRef.current) {
      const w = widthMm / 1000;
      const h = heightMm / 1000;
      const z = depthMm / 1000;
      const pos = (v: number[]) => v.map((n) => `${n.toFixed(4)}m`).join(" ");
      const points: [string, number[], string | null][] = [
        ["w0", [-w / 2, h + 0.07, z], null],
        ["w1", [w / 2, h + 0.07, z], null],
        ["h0", [w / 2 + 0.07, 0, z / 2], null],
        ["h1", [w / 2 + 0.07, h, z / 2], null],
        ["lw", [0, h + 0.07, z], `${cm(widthMm)} cm`],
        ["lh", [w / 2 + 0.07, h / 2, z / 2], `${cm(heightMm)} cm`],
      ];
      for (const [name, at, label] of points) {
        const el = document.createElement("div");
        el.slot = `hotspot-${name}`;
        el.setAttribute("data-position", pos(at));
        if (label) {
          el.textContent = label;
          el.className = "border-line bg-surface text-ink pointer-events-none rounded-full border px-2 py-1 text-xs font-semibold whitespace-nowrap tabular-nums";
        } else {
          el.className = "pointer-events-none size-px";
        }
        mv.appendChild(el);
      }
    }
    requestAnimationFrame(drawLines);
    setTimeout(drawLines, 200);
  }, [widthMm, heightMm, depthMm, drawLines]);

  /* create the viewer once the web component has loaded */
  useEffect(() => {
    let cancelled = false;
    const container = host.current;
    import("@google/model-viewer")
      .then(() => {
        if (cancelled || !container) return;
        const mv = document.createElement("model-viewer") as ModelViewer;
        const attrs: Record<string, string> = {
          alt: `${product.name} in 3D`,
          "camera-controls": "",
          "touch-action": "pan-y",
          "interaction-prompt": "none",
          "camera-orbit": ORBIT,
          "min-camera-orbit": "auto 35deg auto",
          "max-camera-orbit": "auto 100deg auto",
          "field-of-view": "30deg",
          "interpolation-decay": "140",
          "environment-image": "neutral",
          "shadow-intensity": "1",
          "shadow-softness": "0.9",
          exposure: "1.05",
          ar: "",
          // Android: Scene Viewer (Google app); where it is missing, the next tap tries WebXR in Chrome.
          "ar-modes": "scene-viewer webxr quick-look",
          "ios-src": modelFile(product, "usdz"),
          "ar-scale": "fixed",
          "ar-placement": "wall",
        };
        for (const [key, value] of Object.entries(attrs)) mv.setAttribute(key, value);
        mv.style.cssText = "width:100%;height:100%;background:transparent;--poster-color:transparent";
        mv.innerHTML = '<button slot="ar-button" hidden></button><div slot="progress-bar"></div>';

        mv.addEventListener("progress", (e) => setProgress(Math.round(((e as unknown as CustomEvent<{ totalProgress?: number }>).detail?.totalProgress ?? 0) * 100)));
        mv.addEventListener("error", () => setStatus("error"));
        mv.addEventListener("load", () => {
          setStatus("ready");
          buildDims();
          resetView();
          mv.jumpCameraToGoal?.();
        });
        mv.addEventListener("camera-change", (e) => {
          if ((e as CustomEvent).detail?.source === "user-interaction") {
            turned.current = true;
            setHintGone(true);
          }
          requestAnimationFrame(drawLines);
        });

        mv.src = modelFile(product, "glb");
        container.appendChild(mv);
        viewer.current = mv;
      })
      .catch(() => setStatus("error"));
    const onResize = () => requestAnimationFrame(drawLines);
    window.addEventListener("resize", onResize);
    return () => {
      cancelled = true;
      window.removeEventListener("resize", onResize);
      viewer.current?.remove();
      viewer.current = null;
    };
  }, [product, buildDims, resetView, drawLines]);

  /* measurements on and off */
  useEffect(() => {
    sizeOnRef.current = sizeOn;
    buildDims();
    if (!turned.current) resetView();
  }, [sizeOn, buildDims, resetView]);

  /* full screen: the stage covers the window; Esc closes it (or the QR box first) */
  useEffect(() => {
    document.body.style.overflow = full ? "hidden" : "";
    const timer = setTimeout(drawLines, 60);
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      if (qr) setQr(null);
      else if (full) setFull(false);
    };
    document.addEventListener("keydown", onKey);
    return () => {
      clearTimeout(timer);
      document.body.style.overflow = "";
      document.removeEventListener("keydown", onKey);
    };
  }, [full, qr, drawLines]);

  /* AR on phones; on computers a QR code that opens this page in 3D */
  const viewInRoom = () => {
    const mv = viewer.current;
    if (mv?.canActivateAR) {
      mv.activateAR?.();
      return;
    }
    if (qr) {
      setQr(null);
      return;
    }
    setHintGone(true);
    if (window.matchMedia("(pointer: coarse)").matches) {
      // iPhone or iPad here means a browser that cannot open AR Quick Look, such as the Google app.
      const apple = /iPad|iPhone|iPod/.test(navigator.userAgent) || (/Macintosh/.test(navigator.userAgent) && navigator.maxTouchPoints > 1);
      setQr({
        svg: null,
        text: apple
          ? "„Im Raum ansehen“ funktioniert in diesem Browser nicht. Öffne die Seite in Safari."
          : "„Im Raum ansehen“ funktioniert auf diesem Gerät nicht. Dafür brauchst du ein iPhone, ein iPad oder ein Android-Smartphone, das Augmented Reality unterstützt.",
      });
      return;
    }
    const url = `${window.location.origin}/products/${product.slug}#3d`;
    const text = "Scanne den Code mit der Handykamera. Das Paneel öffnet sich in 3D, und mit „Im Raum ansehen“ siehst du es in Originalgröße in deinem Raum.";
    setQr({ svg: null, text });
    import("qrcode-generator")
      .then(({ default: qrcode }) => {
        const code = qrcode(0, "M");
        code.addData(url);
        code.make();
        setQr({ svg: code.createSvgTag({ cellSize: 4, margin: 0, scalable: true }), text });
      })
      .catch(() => setQr({ svg: null, text: `${text} ${url}` }));
  };

  const chip =
    "border-line bg-surface text-ink inline-flex cursor-pointer items-center gap-1.5 rounded-full border px-3 py-2 text-xs font-semibold aria-pressed:border-ink aria-pressed:bg-ink aria-pressed:text-surface";

  return (
    <div
      ref={stage}
      className={
        full
          ? "bg-sand fixed inset-0 z-[70] pt-[env(safe-area-inset-top)] pr-[env(safe-area-inset-right)] pb-[env(safe-area-inset-bottom)] pl-[env(safe-area-inset-left)]"
          : "relative h-full w-full"
      }
      role="region"
      aria-label={`3D-Ansicht: ${product.name}`}
      style={{ background: "radial-gradient(120% 90% at 50% 20%, #f1ece4, #d9d1c5)" }}
    >
      <div ref={host} className="h-full w-full" />
      <svg ref={lines} aria-hidden="true" className="stroke-ink pointer-events-none absolute inset-0 h-full w-full [stroke-width:1.4]" />

      {status !== "ready" && (
        <div className="text-ink absolute top-1/2 left-1/2 grid -translate-x-1/2 -translate-y-1/2 justify-items-center gap-2 text-center text-xs">
          {status === "error" ? (
            <span className="max-w-56">Das 3D-Modell konnte nicht geladen werden. Bitte lade die Seite neu.</span>
          ) : (
            <>
              <span>3D-Modell wird geladen</span>
              <span className="bg-line block h-0.5 w-40 overflow-hidden rounded">
                <span className="bg-ink block h-full transition-[width]" style={{ width: `${progress}%` }} />
              </span>
            </>
          )}
        </div>
      )}

      <div className="pointer-events-none absolute inset-0 flex flex-col justify-between p-3">
        <div className="flex flex-wrap items-start justify-between gap-2">
          {sizeOn ? (
            <span className="bg-ink text-surface rounded-full px-3 py-1.5 text-xs font-medium">{sizeText} · Originalgröße</span>
          ) : (
            <span />
          )}
          <span
            className={`border-line bg-surface text-ink rounded-full border px-3 py-1.5 text-xs transition-opacity duration-500 ${hintGone ? "opacity-0" : ""}`}
          >
            Ziehen zum Drehen · Zoomen mit zwei Fingern oder Mausrad
          </span>
        </div>
        <div className="pointer-events-auto flex flex-wrap justify-center gap-2">
          <button type="button" className={chip} aria-pressed={sizeOn} onClick={() => setSizeOn((on) => !on)}>
            <svg viewBox="0 0 24 24" className="size-4" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" aria-hidden="true">
              <path d="M3 7h18M3 4v6M21 4v6M7 21V11M4 11h6M4 21h6" />
            </svg>
            Maße
          </button>
          <button
            type="button"
            className={chip}
            onClick={() => {
              turned.current = false;
              resetView();
            }}
          >
            <svg viewBox="0 0 24 24" className="size-4" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
              <path d="M4 12a8 8 0 1 0 2.4-5.7" />
              <path d="M4 4v4h4" />
            </svg>
            Zurück zum Start
          </button>
          <button type="button" className={chip} onClick={viewInRoom}>
            <svg viewBox="0 0 24 24" className="size-4" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
              <path d="M3 8V4h4M17 4h4v4M21 16v4h-4M7 20H3v-4" />
              <path d="M12 7.5l4 2.2v4.6l-4 2.2-4-2.2V9.7z" />
            </svg>
            Im Raum ansehen
          </button>
          <button type="button" className={chip} aria-pressed={full} onClick={() => setFull((on) => !on)}>
            <svg viewBox="0 0 24 24" className="size-4" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
              <path d="M4 9V4h5M15 4h5v5M20 15v5h-5M9 20H4v-5" />
            </svg>
            {full ? "Vollbild schließen" : "Vollbild"}
          </button>
        </div>
      </div>

      {qr && (
        <div className="border-line bg-surface text-ink absolute right-3 bottom-16 grid w-[min(16rem,calc(100%-1.5rem))] gap-2 rounded-xl border p-4 text-xs leading-relaxed shadow-lg">
          <b className="text-sm">Das Paneel im Raum ansehen</b>
          {qr.svg && <div className="mx-auto w-36 [&_svg]:block [&_svg]:h-auto [&_svg]:w-full" dangerouslySetInnerHTML={{ __html: qr.svg }} />}
          <p>{qr.text}</p>
          <button type="button" className={`${chip} justify-self-start`} onClick={() => setQr(null)}>
            Schließen
          </button>
        </div>
      )}
    </div>
  );
}
